window.PAGES = window.PAGES || {};
window.PAGES["day2-theory"] = {"title": "OCI Security, Governance & Cost Management \u2014 Day 2 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 2 \u2014 ADDITIONAL WIDGET STYLES\n   (CIA triad, castle defense-in-depth, zero trust flow,\n   cloud guard console, security zones, cost dashboards,\n   governance pyramid, org tree, cert preview)\n   ============================================================ */\n\n/* --- CIA triad --- */\n.cia-wrap{display:flex; justify-content:center; padding:20px 0;}\n.cia-triangle{position:relative; width:340px; height:300px;}\n.cia-node{\n  position:absolute; width:130px; padding:14px; border-radius:var(--radius-sm); text-align:center;\n  border:1px solid var(--border-strong); background:var(--panel); cursor:pointer; transition:.25s; font-size:13px;\n}\n.cia-node:hover, .cia-node.active{transform:scale(1.06); box-shadow:var(--shadow-sm);}\n.cia-node.confidentiality{top:0; left:50%; transform:translateX(-50%);}\n.cia-node.confidentiality.active, .cia-node.confidentiality:hover{border-color:var(--blue); color:var(--blue);}\n.cia-node.integrity{bottom:0; left:0;}\n.cia-node.integrity.active, .cia-node.integrity:hover{border-color:var(--amber); color:var(--amber);}\n.cia-node.availability{bottom:0; right:0;}\n.cia-node.availability.active, .cia-node.availability:hover{border-color:var(--green); color:var(--green);}\n.cia-triangle svg{position:absolute; inset:0; z-index:-1;}\n.cia-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px; margin-top:16px; font-size:13.5px; color:var(--text-2); min-height:70px;}\n.cia-examples{display:flex; flex-wrap:wrap; gap:8px; margin-top:10px;}\n.cia-examples span{font-size:11px; background:var(--panel-2); border:1px solid var(--border); padding:4px 10px; border-radius:999px;}\n\n/* --- Defense in depth castle --- */\n.castle-wrap{display:flex; flex-direction:column; gap:6px; align-items:center;}\n.castle-layer{\n  width:100%; max-width:640px; padding:12px 18px; border-radius:10px; border:1px solid var(--border-strong);\n  background:var(--panel); display:flex; justify-content:space-between; align-items:center; transition:.35s; font-size:13px;\n}\n.castle-layer.removed{opacity:.15; transform:scale(.97); filter:blur(1px);}\n.castle-layer .cl-name{font-weight:700;}\n.castle-layer button{font-size:11px;}\n#castle-msg{min-height:20px;}\n\n/* --- Zero trust flow --- */\n.zt-flow{display:flex; align-items:center; justify-content:space-between; gap:8px; overflow-x:auto; padding:10px 0;}\n.zt-node{flex:1; min-width:110px; text-align:center; padding:14px 8px; border-radius:var(--radius-sm); border:1px solid var(--border); background:var(--panel); font-size:12px; transition:.3s;}\n.zt-node.active{border-color:var(--red-bright); box-shadow:0 0 0 3px var(--red-dim);}\n.zt-arrow{color:var(--text-3); flex-shrink:0;}\n\n/* --- security tool ecosystem --- */\n.tool-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(130px,1fr)); gap:10px;}\n.tool-chip{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; text-align:center; font-size:12px; transition:.2s;}\n.tool-chip:hover{border-color:var(--border-strong); transform:translateY(-2px);}\n.tool-chip.native{border-top:2px solid var(--red-bright);}\n.tool-chip.thirdparty{border-top:2px solid var(--blue);}\n\n/* --- cloud guard console --- */\n.cg-toggle-row{display:flex; align-items:center; justify-content:space-between; padding:14px 18px; background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:14px;}\n.switch{position:relative; width:44px; height:24px; flex-shrink:0;}\n.switch input{opacity:0; width:0; height:0;}\n.switch .slider{position:absolute; inset:0; background:var(--panel-2); border:1px solid var(--border-strong); border-radius:999px; cursor:pointer; transition:.25s;}\n.switch .slider::before{content:\"\"; position:absolute; width:16px; height:16px; left:3px; top:2px; background:var(--text-3); border-radius:50%; transition:.25s;}\n.switch input:checked + .slider{background:var(--red-dim); border-color:var(--red);}\n.switch input:checked + .slider::before{transform:translateX(20px); background:var(--red-bright);}\n.detector-row{display:flex; align-items:center; justify-content:space-between; padding:12px 14px; border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:8px; font-size:13px;}\n.responder-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; cursor:pointer; transition:.2s; text-align:center;}\n.responder-card.selected{border-color:var(--red); background:var(--red-dim);}\n.problem-pipeline{display:flex; align-items:center; gap:4px; overflow-x:auto; padding:14px 0;}\n.pipe-step{flex-shrink:0; min-width:100px; text-align:center; padding:12px 6px; border-radius:8px; background:var(--panel); border:1px solid var(--border); font-size:11px; transition:.3s;}\n.pipe-step.lit{border-color:var(--amber); box-shadow:0 0 0 3px var(--amber-dim); color:var(--amber);}\n.pipe-arrow{color:var(--text-3); flex-shrink:0; font-size:14px;}\n\n/* --- security zone console --- */\n.sz-console{background:var(--panel); border:1px solid var(--border-strong); border-radius:var(--radius); padding:20px;}\n.sz-attempt-row{display:flex; gap:10px; flex-wrap:wrap; margin:14px 0;}\n.sz-result{margin-top:12px; padding:12px 14px; border-radius:8px; font-size:13px; display:none;}\n.sz-result.blocked{display:block; background:var(--red-dim); color:var(--red-bright); border:1px solid rgba(199,70,52,.35);}\n.sz-result.allowed{display:block; background:var(--green-dim); color:var(--green); border:1px solid rgba(62,194,143,.35);}\n\n/* --- security advisor score --- */\n.score-ring-wrap{display:flex; align-items:center; gap:28px; flex-wrap:wrap;}\n.score-ring{width:130px; height:130px; border-radius:50%; position:relative; background:conic-gradient(var(--green) calc(var(--score,60)*3.6deg), var(--panel-2) 0); transition:background .6s ease; flex-shrink:0;}\n.score-ring::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--panel);}\n.score-ring span{position:relative; display:flex; align-items:center; justify-content:center; height:100%; font-family:var(--font-display); font-size:26px; font-weight:700;}\n.rec-row{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:12px 14px; border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:8px; font-size:13px;}\n.rec-row.fixed{opacity:.45;}\n.priority-pill{font-size:10px; padding:2px 8px; border-radius:20px; text-transform:uppercase; letter-spacing:.04em;}\n.priority-high{background:var(--red-dim); color:var(--red-bright);}\n.priority-med{background:var(--amber-dim); color:var(--amber);}\n.priority-low{background:var(--blue-dim); color:var(--blue);}\n\n/* --- decision tree --- */\n.dtree{display:flex; flex-direction:column; align-items:center; gap:10px;}\n.dtree .dt-q{background:var(--panel); border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:12px 18px; font-size:13px; text-align:center; max-width:420px;}\n.dtree .dt-opts{display:flex; gap:10px; flex-wrap:wrap; justify-content:center;}\n.dtree .dt-result{background:var(--red-dim); border:1px solid rgba(199,70,52,.35); color:var(--red-bright); border-radius:var(--radius-sm); padding:14px; text-align:center; max-width:420px; font-size:13px; display:none;}\n\n/* --- billing dashboard --- */\n.bill-stats{display:grid; grid-template-columns:repeat(4,1fr); gap:12px;}\n@media (max-width:800px){.bill-stats{grid-template-columns:1fr 1fr;}}\n.bill-stat{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px;}\n.bill-stat .label{font-size:10px; text-transform:uppercase; color:var(--text-3); letter-spacing:.06em;}\n.bill-stat .val{font-family:var(--font-display); font-size:20px; margin-top:4px;}\n.bill-stat .delta{font-size:11px; margin-top:2px;}\n.bill-stat .delta.up{color:var(--red-bright);}\n.bill-stat .delta.down{color:var(--green);}\ncanvas#costTrendChart, canvas#costPieChart{width:100%;}\n.cost-filters{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px;}\n.pie-legend{display:flex; flex-direction:column; gap:6px; font-size:12px; margin-top:10px;}\n.pie-legend span.sw{width:10px; height:10px; display:inline-block; border-radius:3px; margin-right:6px;}\n\n/* --- budget wizard --- */\n.wizard-steps{display:flex; gap:6px; margin-bottom:20px;}\n.wizard-steps div{flex:1; height:4px; border-radius:4px; background:var(--panel-2);}\n.wizard-steps div.done{background:var(--red-bright);}\n.wizard-panel{display:none;}\n.wizard-panel.active{display:block;}\n.field-row{margin-bottom:14px;}\n.field-row label{display:block; font-size:12px; color:var(--text-3); margin-bottom:6px; text-transform:uppercase; letter-spacing:.05em;}\n.budget-gauge{height:14px; border-radius:8px; background:var(--panel-2); overflow:hidden; margin:10px 0;}\n.budget-gauge-fill{height:100%; background:linear-gradient(90deg,var(--green),var(--amber),var(--red)); width:0%; transition:width .6s ease;}\n\n/* --- marketplace --- */\n.mp-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(160px,1fr)); gap:14px;}\n.mp-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; cursor:pointer; transition:.2s; text-align:center;}\n.mp-card:hover{border-color:var(--red); transform:translateY(-3px);}\n.mp-card .mp-ic{font-size:26px; margin-bottom:8px;}\n.mp-deploy-status{margin-top:14px; font-size:13px; display:none; padding:10px; border-radius:8px; background:var(--green-dim); color:var(--green);}\n\n/* --- right sizing --- */\n.rs-shape{display:flex; align-items:center; justify-content:space-between; padding:12px 16px; border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:8px; cursor:pointer; font-size:13px;}\n.rs-shape.selected{border-color:var(--red); background:var(--red-dim);}\n.rs-savings{background:var(--green-dim); border:1px solid rgba(62,194,143,.35); color:var(--green); border-radius:var(--radius-sm); padding:14px; margin-top:14px; display:none;}\n\n/* --- governance pyramid --- */\n.pyramid{display:flex; flex-direction:column; align-items:center; gap:4px; margin:20px 0;}\n.pyr-tier{padding:14px; text-align:center; border-radius:8px; border:1px solid var(--border-strong); background:var(--panel); font-size:12.5px; transition:.2s; cursor:default;}\n.pyr-tier:hover{border-color:var(--red);}\n.pyr-detail{background:var(--panel); border-radius:var(--radius-sm); padding:14px; margin-top:10px; font-size:13px; color:var(--text-2); min-height:50px;}\n\n/* --- org tree / hierarchy --- */\n.org-tree{font-size:13px;}\n\n/* --- compliance matrix --- */\n.compliance-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:10px;}\n.compliance-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; text-align:center; font-size:12.5px; cursor:pointer; transition:.2s;}\n.compliance-card:hover{border-color:var(--blue);}\n\n/* --- drag and drop / match --- */\n.dnd-zone{min-height:50px; border:1px dashed var(--border-strong); border-radius:8px; padding:8px; display:flex; flex-wrap:wrap; gap:6px; align-items:center;}\n.dnd-item{background:var(--panel-2); border:1px solid var(--border-strong); border-radius:6px; padding:6px 12px; font-size:12px; cursor:grab;}\n.dnd-item.placed{cursor:default;}\n\n/* --- certificate preview --- */\n.cert-frame{max-width:640px; margin:0 auto; border:2px solid var(--red); border-radius:var(--radius); padding:40px; text-align:center; background:linear-gradient(160deg,var(--panel),var(--panel-2)); position:relative; overflow:hidden;}\n.cert-frame::before{content:\"\"; position:absolute; inset:0; background:repeating-linear-gradient(45deg, rgba(199,70,52,0.04) 0 12px, transparent 12px 24px); pointer-events:none;}\n.cert-frame h3{font-family:var(--font-display); font-size:22px; margin:14px 0 4px;}\n.cert-name{font-size:24px; font-family:var(--font-display); color:var(--red-bright); margin:16px 0; border-bottom:1px solid var(--border-strong); display:inline-block; padding-bottom:6px; min-width:260px;}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Security &amp; Governance \u00b7 Day 2</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search security, cost, governance topics\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Security Fundamentals</div>\n      <a class=\"nav-link\" href=\"#sec-cia\"><span class=\"num\">01</span>CIA Triad</a>\n      <a class=\"nav-link\" href=\"#sec-defense\"><span class=\"num\">02</span>Defense in Depth</a>\n      <a class=\"nav-link\" href=\"#sec-zerotrust\"><span class=\"num\">03</span>Zero Trust</a>\n      <a class=\"nav-link\" href=\"#sec-sharedresp\"><span class=\"num\">04</span>Shared Responsibility</a>\n      <a class=\"nav-link\" href=\"#sec-toolecosystem\"><span class=\"num\">05</span>Security Tool Ecosystem</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 Cloud Guard</div>\n      <a class=\"nav-link\" href=\"#sec-cloudguard\"><span class=\"num\">06</span>Cloud Guard Architecture</a>\n      <a class=\"nav-link\" href=\"#sec-detectors\"><span class=\"num\">07</span>Detectors</a>\n      <a class=\"nav-link\" href=\"#sec-responders\"><span class=\"num\">08</span>Responders</a>\n      <a class=\"nav-link\" href=\"#sec-lifecycle\"><span class=\"num\">09</span>Problem Lifecycle</a>\n      <a class=\"nav-link\" href=\"#sec-seczones\"><span class=\"num\">10</span>Security Zones</a>\n      <a class=\"nav-link\" href=\"#sec-secadvisor\"><span class=\"num\">11</span>Security Advisor</a>\n      <a class=\"nav-link\" href=\"#sec-cgdeploy\"><span class=\"num\">12</span>Tenancy vs Compartment</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 Cost Management</div>\n      <a class=\"nav-link\" href=\"#sec-billing\"><span class=\"num\">13</span>Billing Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-budgets\"><span class=\"num\">14</span>Budgets</a>\n      <a class=\"nav-link\" href=\"#sec-costanalysis\"><span class=\"num\">15</span>Cost Analysis</a>\n      <a class=\"nav-link\" href=\"#sec-byol\"><span class=\"num\">16</span>BYOL vs License Included</a>\n      <a class=\"nav-link\" href=\"#sec-marketplace\"><span class=\"num\">17</span>OCI Marketplace</a>\n      <a class=\"nav-link\" href=\"#sec-rightsizing\"><span class=\"num\">18</span>Right Sizing</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Governance</div>\n      <a class=\"nav-link\" href=\"#sec-governance\"><span class=\"num\">19</span>Governance Pyramid</a>\n      <a class=\"nav-link\" href=\"#sec-limits\"><span class=\"num\">20</span>Service Limits</a>\n      <a class=\"nav-link\" href=\"#sec-quotadesigner\"><span class=\"num\">21</span>Quota Designer</a>\n      <a class=\"nav-link\" href=\"#sec-cladvisor\"><span class=\"num\">22</span>Cloud Advisor</a>\n      <a class=\"nav-link\" href=\"#sec-orgmgmt\"><span class=\"num\">23</span>Organization Management</a>\n      <a class=\"nav-link\" href=\"#sec-compliance\"><span class=\"num\">24</span>Compliance</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Hands-On</div>\n      <a class=\"nav-link\" href=\"#sec-console2\"><span class=\"num\">25</span>Console Simulator</a>\n      <a class=\"nav-link\" href=\"#sec-cli2\"><span class=\"num\">26</span>CLI Terminal</a>\n      <a class=\"nav-link\" href=\"#sec-troubleshoot2\"><span class=\"num\">27</span>Troubleshooting Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Wrap-Up</div>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet2\"><span class=\"num\">28</span>Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards2\"><span class=\"num\">29</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-quiz2\"><span class=\"num\">30</span>Certification Quiz</a>\n      <a class=\"nav-link\" href=\"#sec-cert2\"><span class=\"num\">31</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Security &amp; Governance Track</span>\n      <h1>Day 2: Secure it,<br>govern it, <span class=\"accent\">afford it.</span></h1>\n      <p class=\"lede\">Security fundamentals, Cloud Guard, Security Zones, cost management, and governance \u2014 with live simulators standing in for a real tenancy.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>31</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Certification MCQs</span></div>\n        <div class=\"hstat\"><b>9</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-cia\" class=\"btn btn-primary\">Start learning \u2192</a>\n        <a href=\"#sec-quiz2\" class=\"btn btn-ghost\">Jump to certification quiz</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 CIA TRIAD -->\n<section class=\"chapter reveal\" id=\"sec-cia\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Security Fundamentals</span></div>\n  <h2>The CIA Triad</h2>\n  <p class=\"dek\">Every security control ultimately protects one of three properties. Click a corner to see what breaks when it fails.</p>\n  <div class=\"cia-wrap\"><div class=\"cia-triangle\">\n    <svg viewBox=\"0 0 340 300\"><polygon points=\"170,20 20,270 320,270\" fill=\"none\" stroke=\"var(--border-strong)\" stroke-width=\"2\"/></svg>\n    <div class=\"cia-node confidentiality\" data-k=\"confidentiality\"><h4>\ud83d\udd12 Confidentiality</h4><p style=\"font-size:11px; color:var(--text-3);\">Only authorized parties see the data</p></div>\n    <div class=\"cia-node integrity\" data-k=\"integrity\"><h4>\u2705 Integrity</h4><p style=\"font-size:11px; color:var(--text-3);\">Data is accurate &amp; unaltered</p></div>\n    <div class=\"cia-node availability\" data-k=\"availability\"><h4>\u26a1 Availability</h4><p style=\"font-size:11px; color:var(--text-3);\">Systems are up when needed</p></div>\n  </div></div>\n  <div class=\"cia-detail\" id=\"cia-detail\">Click Confidentiality, Integrity, or Availability above to see a real-world failure scenario.</div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>Every security requirement on the exam maps back to C, I, or A \u2014 if you can't decide which control to apply, ask which of the three properties is at risk.</div></div>\n</section>\n\n<!-- 02 DEFENSE IN DEPTH -->\n<section class=\"chapter reveal\" id=\"sec-defense\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Security Fundamentals</span></div>\n  <h2>Defense in Depth</h2>\n  <p class=\"dek\">No single control is trusted alone. Remove a layer below and see how far an attacker gets.</p>\n  <div class=\"panel\">\n    <div class=\"castle-wrap\" id=\"castle-layers\"></div>\n    <p class=\"center small mt-lg\" id=\"castle-msg\">All 8 layers intact. An attacker is stopped immediately.</p>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"castle-reset\">\u21ba Restore all layers</button> <button class=\"chip-btn\" id=\"castle-attack\">\ud83d\udde1 Simulate attack</button></div>\n  </div>\n  <div class=\"callout callout-trap\"><div class=\"ic\">\u26a0\ufe0f</div><div><b>Common Trap</b>Defense in depth doesn't mean \"add more tools\" \u2014 it means independent controls at different layers, so a single misconfiguration (e.g. a public bucket) isn't the only thing standing between an attacker and your data.</div></div>\n</section>\n\n<!-- 03 ZERO TRUST -->\n<section class=\"chapter reveal\" id=\"sec-zerotrust\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Security Fundamentals</span></div>\n  <h2>Zero Trust</h2>\n  <p class=\"dek\">\"Never trust, always verify.\" Every request is authenticated and authorized, regardless of network location.</p>\n  <div class=\"panel\">\n    <div class=\"zt-flow\" id=\"zt-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"zt-play\">\u25b6 Walk through a request</button></div>\n    <p class=\"small center mt-lg\" id=\"zt-msg\">Click play to step through Zero Trust evaluation for a single access request.</p>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"card\"><h4>Traditional (perimeter) model</h4><p>Trust is granted once inside the network boundary \u2014 a VPN login unlocks broad access.</p></div>\n    <div class=\"card\"><h4>Zero Trust model</h4><p>Every request re-verifies identity, device posture, and risk \u2014 regardless of network location, every time.</p></div>\n  </div>\n</section>\n\n<!-- 04 SHARED RESPONSIBILITY (security-focused) -->\n<section class=\"chapter reveal\" id=\"sec-sharedresp\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Security Fundamentals</span></div>\n  <h2>Shared Responsibility \u2014 Security Lens</h2>\n  <p class=\"dek\">Move the slider between IaaS, PaaS, and SaaS and watch each control area shift ownership.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"sr-model-btns\">\n      <button class=\"chip-btn active\" data-model=\"iaas\">IaaS</button>\n      <button class=\"chip-btn\" data-model=\"paas\">PaaS</button>\n      <button class=\"chip-btn\" data-model=\"saas\">SaaS</button>\n    </div>\n    <div class=\"resp-layers\" id=\"sr-security-layers\"></div>\n  </div>\n</section>\n\n<!-- 05 SECURITY TOOL ECOSYSTEM -->\n<section class=\"chapter reveal\" id=\"sec-toolecosystem\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Security Fundamentals</span></div>\n  <h2>Security Tool Ecosystem</h2>\n  <p class=\"dek\">OCI-native controls versus common third-party tools you'll see referenced on scenario questions.</p>\n  <h3>OCI Native</h3>\n  <div class=\"tool-grid\">\n    <div class=\"tool-chip native\">Cloud Guard</div><div class=\"tool-chip native\">Vault (KMS)</div><div class=\"tool-chip native\">WAF</div>\n    <div class=\"tool-chip native\">IAM</div><div class=\"tool-chip native\">Security Zones</div><div class=\"tool-chip native\">Cloud Advisor</div>\n    <div class=\"tool-chip native\">Audit</div><div class=\"tool-chip native\">Logging</div><div class=\"tool-chip native\">Monitoring</div>\n  </div>\n  <h3>Common Third-Party Integrations</h3>\n  <div class=\"tool-grid\">\n    <div class=\"tool-chip thirdparty\">Palo Alto</div><div class=\"tool-chip thirdparty\">CrowdStrike</div><div class=\"tool-chip thirdparty\">Fortinet</div>\n    <div class=\"tool-chip thirdparty\">Splunk</div><div class=\"tool-chip thirdparty\">Qualys</div><div class=\"tool-chip thirdparty\">Tenable</div>\n  </div>\n  <div class=\"callout callout-q\"><div class=\"ic\">\u2753</div><div><b>Interview Question</b>\"Why integrate a third-party SIEM like Splunk when OCI already has Logging and Audit?\" \u2014 Because enterprises usually need one pane of glass across multiple clouds and on-prem systems; OCI streams logs out via Service Connector Hub for that purpose.</div></div>\n</section>\n<!-- 06 CLOUD GUARD ARCHITECTURE -->\n<section class=\"chapter reveal\" id=\"sec-cloudguard\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Cloud Guard Architecture</h2>\n  <p class=\"dek\">Cloud Guard continuously watches your targets, evaluates them against detector recipes, and can automatically respond.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>\ud83c\udfaf Targets</h4><p>The compartments/tenancy Cloud Guard monitors.</p></div>\n    <div class=\"card\"><h4>\ud83e\uddea Detector Recipes</h4><p>Rules that flag misconfigurations, risky activity, or threats.</p></div>\n    <div class=\"card\"><h4>\ud83e\udd16 Responder Recipes</h4><p>Automated or manual actions taken when a problem is detected.</p></div>\n    <div class=\"card\"><h4>\ud83d\udccb Managed Lists</h4><p>Reusable allow/deny lists (IPs, tags) referenced by detector rules.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <div class=\"cg-toggle-row\">\n      <div><strong>Enable Cloud Guard on tenancy</strong><p class=\"small\" style=\"margin:0;\">Applies default detector &amp; responder recipes to the root compartment.</p></div>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"cg-enable-toggle\"><span class=\"slider\"></span></label>\n    </div>\n    <p class=\"small\" id=\"cg-enable-msg\">Cloud Guard is currently <strong>disabled</strong>.</p>\n  </div>\n</section>\n\n<!-- 07 DETECTORS -->\n<section class=\"chapter reveal\" id=\"sec-detectors\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Detector Recipes</h2>\n  <p class=\"dek\">Turn detectors on to see what class of problem each one catches.</p>\n  <div class=\"panel\" id=\"detector-panel\">\n    <div class=\"detector-row\"><span><strong>Configuration Detector</strong> \u2014 flags public buckets, open security lists, weak policies</span><label class=\"switch\"><input type=\"checkbox\" class=\"det-toggle\" data-det=\"config\"><span class=\"slider\"></span></label></div>\n    <div class=\"detector-row\"><span><strong>Activity Detector</strong> \u2014 flags unusual IAM/API activity patterns</span><label class=\"switch\"><input type=\"checkbox\" class=\"det-toggle\" data-det=\"activity\"><span class=\"slider\"></span></label></div>\n    <div class=\"detector-row\"><span><strong>Threat Detector</strong> \u2014 flags known malicious IPs, malware signatures, brute-force attempts</span><label class=\"switch\"><input type=\"checkbox\" class=\"det-toggle\" data-det=\"threat\"><span class=\"slider\"></span></label></div>\n    <p class=\"small mt-lg\" id=\"detector-msg\">Enable a detector to see an example finding.</p>\n  </div>\n</section>\n\n<!-- 08 RESPONDERS -->\n<section class=\"chapter reveal\" id=\"sec-responders\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Responder Recipes</h2>\n  <p class=\"dek\">A problem was detected: a storage bucket was made public. Pick the automated response.</p>\n  <div class=\"grid grid-4\" id=\"responder-cards\">\n    <div class=\"responder-card\" data-r=\"notify\"><h4>\ud83d\udd14 Notify</h4><p style=\"font-size:12px; color:var(--text-3);\">Alert only, no change</p></div>\n    <div class=\"responder-card\" data-r=\"quarantine\"><h4>\ud83e\uddef Quarantine</h4><p style=\"font-size:12px; color:var(--text-3);\">Isolate the resource</p></div>\n    <div class=\"responder-card\" data-r=\"removeip\"><h4>\ud83d\udeab Remove Public IP</h4><p style=\"font-size:12px; color:var(--text-3);\">Strip external exposure</p></div>\n    <div class=\"responder-card\" data-r=\"disable\"><h4>\u26d4 Disable User</h4><p style=\"font-size:12px; color:var(--text-3);\">Suspend the responsible identity</p></div>\n  </div>\n  <p class=\"small mt-lg\" id=\"responder-msg\">Select a responder action to preview its effect on the public bucket.</p>\n</section>\n\n<!-- 09 PROBLEM LIFECYCLE -->\n<section class=\"chapter reveal\" id=\"sec-lifecycle\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Problem Lifecycle</h2>\n  <p class=\"dek\">Every Cloud Guard finding moves through the same pipeline. Press play to animate it.</p>\n  <div class=\"panel\">\n    <div class=\"problem-pipeline\" id=\"lifecycle-pipeline\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"lifecycle-play\">\u25b6 Animate lifecycle</button></div>\n  </div>\n</section>\n\n<!-- 10 SECURITY ZONES -->\n<section class=\"chapter reveal\" id=\"sec-seczones\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Security Zones</h2>\n  <p class=\"dek\">A Security Zone enforces a recipe of hard-blocking policies on a compartment \u2014 non-compliant actions are rejected outright, not just flagged.</p>\n  <div class=\"sz-console\">\n    <div class=\"cg-toggle-row\" style=\"margin-bottom:14px;\">\n      <div><strong>Security Zone: \"prod-zone\"</strong><p class=\"small\" style=\"margin:0;\">Recipe: Maximum Security</p></div>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"sz-enable\" checked><span class=\"slider\"></span></label>\n    </div>\n    <p class=\"small\">Try these actions inside the Security Zone compartment:</p>\n    <div class=\"sz-attempt-row\">\n      <button class=\"chip-btn\" data-sz=\"bucket\">Create public bucket</button>\n      <button class=\"chip-btn\" data-sz=\"igw\">Attach Internet Gateway</button>\n      <button class=\"chip-btn\" data-sz=\"publicip\">Assign public IP</button>\n      <button class=\"chip-btn\" data-sz=\"weakenc\">Use weak/no encryption</button>\n    </div>\n    <div class=\"sz-result\" id=\"sz-result\"></div>\n  </div>\n  <div class=\"callout callout-warn\"><div class=\"ic\">\u26a0\ufe0f</div><div><b>Exam Warning</b>Security Zones <em>prevent</em> non-compliant actions at request time; Cloud Guard <em>detects and responds</em> after the fact. They're complementary, not interchangeable.</div></div>\n</section>\n\n<!-- 11 SECURITY ADVISOR -->\n<section class=\"chapter reveal\" id=\"sec-secadvisor\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Security Advisor</h2>\n  <p class=\"dek\">A running security score based on unresolved recommendations. Fix issues below and watch the score climb.</p>\n  <div class=\"panel\">\n    <div class=\"score-ring-wrap\">\n      <div class=\"score-ring\" id=\"advisor-ring\" style=\"--score:55;\"><span id=\"advisor-score-val\">55</span></div>\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"rec-row\" data-fix=\"mfa\"><span><span class=\"priority-pill priority-high\">High</span> Enable MFA for all admin users</span><button class=\"chip-btn active fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-fix=\"publicbucket\"><span><span class=\"priority-pill priority-high\">High</span> Remove public access from Object Storage bucket</span><button class=\"chip-btn active fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-fix=\"oldkeys\"><span><span class=\"priority-pill priority-med\">Medium</span> Rotate API keys older than 90 days</span><button class=\"chip-btn active fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-fix=\"logging\"><span><span class=\"priority-pill priority-low\">Low</span> Enable logging on all compartments</span><button class=\"chip-btn active fix-btn\">Fix</button></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 12 TENANCY VS COMPARTMENT (Cloud Guard deployment) -->\n<section class=\"chapter reveal\" id=\"sec-cgdeploy\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">Cloud Guard</span></div>\n  <h2>Where Should Cloud Guard Be Enabled?</h2>\n  <p class=\"dek\">A decision exercise: root tenancy vs. individual compartment.</p>\n  <div class=\"panel\">\n    <div class=\"dtree\">\n      <div class=\"dt-q\">Do you need consistent, tenancy-wide visibility with minimal ongoing maintenance?</div>\n      <div class=\"dt-opts\"><button class=\"chip-btn\" data-dt=\"yes\">Yes</button><button class=\"chip-btn\" data-dt=\"no\">No \u2014 I need narrow, team-specific scope</button></div>\n      <div class=\"dt-result\" id=\"dt-result-yes\">\u2705 Enable Cloud Guard at the <strong>root/tenancy level</strong>. Advantage: single recipe set, nothing falls through the cracks. Disadvantage: less granular tuning per team.</div>\n      <div class=\"dt-result\" id=\"dt-result-no\">\u2705 Enable Cloud Guard at the <strong>compartment level</strong>. Advantage: tailored detector/responder recipes per team. Disadvantage: more overhead to maintain consistency across compartments.</div>\n    </div>\n  </div>\n</section>\n<!-- 13 BILLING DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-billing\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">Cost Management</span></div>\n  <h2>Billing Dashboard</h2>\n  <p class=\"dek\">A live view of spend, forecast, and service breakdown.</p>\n  <div class=\"bill-stats\">\n    <div class=\"bill-stat\"><div class=\"label\">Month to date</div><div class=\"val\">$4,820</div><div class=\"delta up\">\u25b2 12% vs last month</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">Forecast (EOM)</div><div class=\"val\">$7,150</div><div class=\"delta up\">\u25b2 trending over budget</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">Daily average</div><div class=\"val\">$231</div><div class=\"delta down\">\u25bc 4% this week</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">Credits remaining</div><div class=\"val\">$1,940</div><div class=\"delta down\">\u25bc burns in ~8 days</div></div>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"panel\"><h4 style=\"margin-bottom:10px;\">Daily spend trend</h4><canvas id=\"costTrendChart\" width=\"400\" height=\"200\"></canvas></div>\n    <div class=\"panel\"><h4 style=\"margin-bottom:10px;\">Spend by service</h4><canvas id=\"costPieChart\" width=\"260\" height=\"200\"></canvas><div class=\"pie-legend\" id=\"pie-legend\"></div></div>\n  </div>\n</section>\n\n<!-- 14 BUDGETS WIZARD -->\n<section class=\"chapter reveal\" id=\"sec-budgets\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">Cost Management</span></div>\n  <h2>Create a Budget</h2>\n  <p class=\"dek\">Walk through the same 3 steps as the real OCI Budgets wizard.</p>\n  <div class=\"panel\">\n    <div class=\"wizard-steps\"><div class=\"done\" id=\"wz-bar-1\"></div><div id=\"wz-bar-2\"></div><div id=\"wz-bar-3\"></div></div>\n    <div class=\"wizard-panel active\" id=\"wz-1\">\n      <div class=\"field-row\"><label>Budget amount (USD/month)</label><input type=\"range\" id=\"wz-amount\" min=\"500\" max=\"20000\" step=\"100\" value=\"5000\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Amount: <strong id=\"wz-amount-val\">$5,000</strong></p></div>\n      <div class=\"field-row\"><label>Scope</label><select class=\"mini-input\" id=\"wz-scope\"><option>Entire tenancy</option><option>Compartment: Production</option><option>Compartment: Dev</option></select></div>\n      <button class=\"chip-btn active\" id=\"wz-next-1\">Next \u2192</button>\n    </div>\n    <div class=\"wizard-panel\" id=\"wz-2\">\n      <div class=\"field-row\"><label>Alert threshold (% of budget)</label><input type=\"range\" id=\"wz-threshold\" min=\"50\" max=\"150\" step=\"5\" value=\"80\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Alert at <strong id=\"wz-threshold-val\">80%</strong> of budget</p></div>\n      <div class=\"field-row\"><label>Recipients</label><input type=\"text\" class=\"mini-input\" id=\"wz-recipients\" placeholder=\"finance-team@company.com\" style=\"width:100%;\"></div>\n      <button class=\"chip-btn\" id=\"wz-back-2\">\u2190 Back</button> <button class=\"chip-btn active\" id=\"wz-next-2\">Next \u2192</button>\n    </div>\n    <div class=\"wizard-panel\" id=\"wz-3\">\n      <p><strong>Review:</strong></p>\n      <p class=\"small\" id=\"wz-summary\"></p>\n      <div class=\"budget-gauge\"><div class=\"budget-gauge-fill\" id=\"wz-gauge\"></div></div>\n      <p class=\"small\" id=\"wz-status\"></p>\n      <button class=\"chip-btn\" id=\"wz-back-3\">\u2190 Back</button> <button class=\"chip-btn active\" id=\"wz-create\">\u2713 Create Budget</button>\n      <button class=\"chip-btn\" id=\"wz-simulate-spend\" style=\"display:none;\">\ud83d\udca5 Simulate spend spike past threshold</button>\n    </div>\n  </div>\n</section>\n\n<!-- 15 COST ANALYSIS -->\n<section class=\"chapter reveal\" id=\"sec-costanalysis\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Cost Management</span></div>\n  <h2>Cost Analysis</h2>\n  <p class=\"dek\">Filter spend by service, compartment, or tag \u2014 charts update instantly.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\">\n      <button class=\"chip-btn active\" data-cf=\"all\">All services</button>\n      <button class=\"chip-btn\" data-cf=\"compute\">Compute</button>\n      <button class=\"chip-btn\" data-cf=\"storage\">Storage</button>\n      <button class=\"chip-btn\" data-cf=\"database\">Database</button>\n      <button class=\"chip-btn\" data-cf=\"network\">Networking</button>\n    </div>\n    <canvas id=\"analysisChart\" width=\"600\" height=\"220\"></canvas>\n    <p class=\"small center\" id=\"analysis-total\">Total: $4,820 across all services this month.</p>\n  </div>\n</section>\n\n<!-- 16 BYOL VS LICENSE INCLUDED -->\n<section class=\"chapter reveal\" id=\"sec-byol\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Cost Management</span></div>\n  <h2>BYOL vs License Included</h2>\n  <p class=\"dek\">Select a workload and compare licensing cost strategies.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"byol-workload-btns\">\n      <button class=\"chip-btn active\" data-w=\"small\">Small DB (2 OCPU)</button>\n      <button class=\"chip-btn\" data-w=\"medium\">Medium DB (8 OCPU)</button>\n      <button class=\"chip-btn\" data-w=\"large\">Large DB (32 OCPU)</button>\n    </div>\n    <table class=\"cmp\">\n      <tr><th>Model</th><th>Monthly cost</th><th>Best for</th></tr>\n      <tr><td>License Included</td><td id=\"byol-li-cost\">\u2014</td><td>No existing Oracle licenses; simplest to start</td></tr>\n      <tr><td>BYOL (Bring Your Own License)</td><td id=\"byol-byol-cost\">\u2014</td><td>You already own Oracle licenses with active support</td></tr>\n    </table>\n    <p class=\"small\" id=\"byol-reco\"></p>\n  </div>\n</section>\n\n<!-- 17 MARKETPLACE -->\n<section class=\"chapter reveal\" id=\"sec-marketplace\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Cost Management</span></div>\n  <h2>OCI Marketplace</h2>\n  <p class=\"dek\">Click a listing to simulate deployment.</p>\n  <div class=\"cost-filters\" id=\"mp-cat-btns\">\n    <button class=\"chip-btn active\" data-cat=\"all\">All</button><button class=\"chip-btn\" data-cat=\"db\">Databases</button>\n    <button class=\"chip-btn\" data-cat=\"sec\">Security</button><button class=\"chip-btn\" data-cat=\"mon\">Monitoring</button>\n    <button class=\"chip-btn\" data-cat=\"ai\">AI</button><button class=\"chip-btn\" data-cat=\"net\">Networking</button>\n  </div>\n  <div class=\"mp-grid\" id=\"mp-grid\"></div>\n  <div class=\"mp-deploy-status\" id=\"mp-deploy-status\"></div>\n</section>\n\n<!-- 18 RIGHT SIZING -->\n<section class=\"chapter reveal\" id=\"sec-rightsizing\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Cost Management</span></div>\n  <h2>Right Sizing (Compute Optimizer)</h2>\n  <p class=\"dek\">Select a running VM to see the Advisor's shape recommendation.</p>\n  <div class=\"panel\">\n    <div class=\"rs-shape selected\" data-rs=\"over\"><span><strong>web-vm-prod-01</strong> \u2014 VM.Standard.E4.Flex (8 OCPU) \u2014 avg CPU 9%</span><span class=\"small\">Currently running</span></div>\n    <div class=\"rs-shape\" data-rs=\"under\"><span><strong>batch-vm-nightly</strong> \u2014 VM.Standard.E4.Flex (2 OCPU) \u2014 avg CPU 96%</span><span class=\"small\">Currently running</span></div>\n    <div class=\"rs-savings\" id=\"rs-savings\"></div>\n  </div>\n</section>\n<!-- 19 GOVERNANCE PYRAMID -->\n<section class=\"chapter reveal\" id=\"sec-governance\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Governance</span></div>\n  <h2>Governance Framework</h2>\n  <p class=\"dek\">Click each tier of the pyramid, top to bottom.</p>\n  <div class=\"pyramid\" id=\"gov-pyramid\">\n    <div class=\"pyr-tier\" data-g=\"enterprise\" style=\"width:220px;\">Enterprise Architecture</div>\n    <div class=\"pyr-tier\" data-g=\"landing\" style=\"width:320px;\">Landing Zone</div>\n    <div class=\"pyr-tier\" data-g=\"policies\" style=\"width:420px;\">Policies &amp; Standards</div>\n    <div class=\"pyr-tier\" data-g=\"processes\" style=\"width:520px;\">Operational Processes</div>\n  </div>\n  <div class=\"pyr-detail\" id=\"gov-detail\">Click a tier above for its definition.</div>\n</section>\n\n<!-- 20 SERVICE LIMITS -->\n<section class=\"chapter reveal\" id=\"sec-limits\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Governance</span></div>\n  <h2>Service Limits</h2>\n  <p class=\"dek\">Request a limit increase and watch the approval workflow.</p>\n  <div class=\"panel\">\n    <table class=\"console-table\"><tr><th>Limit</th><th>Current</th><th>Used</th><th></th></tr>\n      <tr><td>compute-core-count</td><td>100</td><td>92</td><td><button class=\"chip-btn active\" id=\"limit-request\">Request increase</button></td></tr>\n    </table>\n    <div class=\"problem-pipeline mt-lg\" id=\"limit-pipeline\"></div>\n    <p class=\"small center\" id=\"limit-msg\">Click \"Request increase\" to start the approval workflow.</p>\n  </div>\n</section>\n\n<!-- 21 QUOTA DESIGNER -->\n<section class=\"chapter reveal\" id=\"sec-quotadesigner\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Governance</span></div>\n  <h2>Quota Designer</h2>\n  <p class=\"dek\">Write a quota statement \u2014 same declarative syntax family as IAM policies.</p>\n  <div class=\"policy-editor\"><textarea id=\"quota-input\" spellcheck=\"false\">set compute quotas instance-count to 20 in compartment Production</textarea></div>\n  <button class=\"chip-btn active\" id=\"quota-validate\" style=\"margin-top:10px;\">Validate syntax</button>\n  <div class=\"policy-verdict\" id=\"quota-verdict\"></div>\n</section>\n\n<!-- 22 CLOUD ADVISOR -->\n<section class=\"chapter reveal\" id=\"sec-cladvisor\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">Governance</span></div>\n  <h2>Cloud Advisor</h2>\n  <p class=\"dek\">Recommendations across five pillars. Fix issues to raise the score.</p>\n  <div class=\"panel\">\n    <div class=\"score-ring-wrap\">\n      <div class=\"score-ring\" id=\"cladvisor-ring\" style=\"--score:62;\"><span id=\"cladvisor-score-val\">62</span></div>\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"rec-row\" data-cafix=\"cost\"><span><span class=\"priority-pill priority-med\">Cost</span> Terminate 3 idle compute instances</span><button class=\"chip-btn active ca-fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-cafix=\"perf\"><span><span class=\"priority-pill priority-low\">Performance</span> Move DB to higher-IOPS volume tier</span><button class=\"chip-btn active ca-fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-cafix=\"avail\"><span><span class=\"priority-pill priority-high\">Availability</span> Spread web tier across 3 ADs</span><button class=\"chip-btn active ca-fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-cafix=\"sec\"><span><span class=\"priority-pill priority-high\">Security</span> Enable MFA for admin group</span><button class=\"chip-btn active ca-fix-btn\">Fix</button></div>\n        <div class=\"rec-row\" data-cafix=\"ops\"><span><span class=\"priority-pill priority-low\">Operational Excellence</span> Enable tagging on untagged resources</span><button class=\"chip-btn active ca-fix-btn\">Fix</button></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 23 ORGANIZATION MANAGEMENT -->\n<section class=\"chapter reveal\" id=\"sec-orgmgmt\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">Governance</span></div>\n  <h2>Organization Management</h2>\n  <p class=\"dek\">A parent tenancy can link and centrally bill for multiple child tenancies.</p>\n  <div class=\"panel\">\n    <div class=\"tree org-tree\">\n      <ul style=\"margin-left:0; border-left:none; padding-left:0;\">\n        <li><div class=\"node root\"><span class=\"ic\">\ud83c\udfdb</span> Parent Organization (Billing root)</div>\n          <ul>\n            <li><div class=\"node\"><span class=\"ic\">\ud83c\udfe2</span> Child Tenancy \u2014 Marketing Dept</div></li>\n            <li><div class=\"node\"><span class=\"ic\">\ud83c\udfe2</span> Child Tenancy \u2014 Engineering Dept</div></li>\n            <li><div class=\"node\"><span class=\"ic\">\ud83c\udfe2</span> Child Tenancy \u2014 Acquired Subsidiary</div></li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>Linked/child tenancies in Organization Management keep IAM fully isolated between departments while consolidating invoices and enabling volume-based discounts at the parent level.</div></div>\n</section>\n\n<!-- 24 COMPLIANCE -->\n<section class=\"chapter reveal\" id=\"sec-compliance\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Governance</span></div>\n  <h2>Compliance</h2>\n  <p class=\"dek\">Click a framework to see what it primarily governs.</p>\n  <div class=\"compliance-grid\" id=\"compliance-grid\">\n    <div class=\"compliance-card\" data-c=\"iso\">ISO 27001</div>\n    <div class=\"compliance-card\" data-c=\"soc\">SOC 1/2</div>\n    <div class=\"compliance-card\" data-c=\"pci\">PCI DSS</div>\n    <div class=\"compliance-card\" data-c=\"hipaa\">HIPAA</div>\n    <div class=\"compliance-card\" data-c=\"gdpr\">GDPR</div>\n    <div class=\"compliance-card\" data-c=\"residency\">Data Residency</div>\n  </div>\n  <div class=\"cia-detail mt-lg\" id=\"compliance-detail\">Click a framework above.</div>\n</section>\n<!-- 25 CONSOLE SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-console2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>OCI Console Simulator</h2>\n  <p class=\"dek\">A simplified Security/Governance console. Everything below is client-side only.</p>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/security</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel2=\"cg\">\ud83d\udee1 Cloud Guard</div>\n        <div data-panel2=\"budgets2\">\ud83d\udcb0 Budgets</div>\n        <div data-panel2=\"advisor2\">\ud83d\udcca Cloud Advisor</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel2\" id=\"panel2-cg\">\n          <table class=\"console-table\"><thead><tr><th>Problem</th><th>Risk</th><th>Resource</th><th>Status</th></tr></thead>\n          <tbody>\n            <tr><td>Public bucket detected</td><td><span class=\"priority-pill priority-high\">High</span></td><td>bkt-invoices</td><td><span class=\"status-pill active\">Open</span></td></tr>\n            <tr><td>Root user API key in use</td><td><span class=\"priority-pill priority-med\">Medium</span></td><td>root</td><td><span class=\"status-pill active\">Open</span></td></tr>\n            <tr><td>Unused security list rule</td><td><span class=\"priority-pill priority-low\">Low</span></td><td>sl-web-tier</td><td><span class=\"status-pill deleted\">Resolved</span></td></tr>\n          </tbody></table>\n        </div>\n        <div class=\"console-panel2\" id=\"panel2-budgets2\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Budget</th><th>Amount</th><th>Spent</th><th>Status</th></tr></thead>\n          <tbody><tr><td>Production Monthly</td><td>$5,000</td><td>$4,820</td><td><span class=\"priority-pill priority-med\">96%</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel2\" id=\"panel2-advisor2\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Recommendation</th><th>Category</th></tr></thead>\n          <tbody><tr><td>Enable MFA for all users</td><td>Security</td></tr><tr><td>Terminate idle instances</td><td>Cost</td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 26 CLI TERMINAL -->\n<section class=\"chapter reveal\" id=\"sec-cli2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>CLI Terminal Simulator</h2>\n  <p class=\"dek\">Try security &amp; governance commands.</p>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">oci-cli \u2014 simulator \u2014 bash</div>\n    <div id=\"term-out2\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"term-input2\" type=\"text\" placeholder=\"type: help\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">help</span>, <span class=\"mono\">oci cloud-guard target list</span>, <span class=\"mono\">oci cloud-guard problem list</span>, <span class=\"mono\">oci budgets budget list</span>, <span class=\"mono\">oci limits value list</span>, <span class=\"mono\">oci organizations organization list</span>, <span class=\"mono\">oci cloud-advisor recommendation list</span>, <span class=\"mono\">clear</span></p>\n</section>\n\n<!-- 27 TROUBLESHOOTING LAB -->\n<section class=\"chapter reveal\" id=\"sec-troubleshoot2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Troubleshooting Lab</h2>\n  <p class=\"dek\">Pick a case, diagnose it.</p>\n  <div class=\"cost-filters\" id=\"ts2-case-btns\">\n    <button class=\"chip-btn active\" data-case=\"cgproblem\">Cloud Guard Problem</button>\n    <button class=\"chip-btn\" data-case=\"szerror\">Security Zone Error</button>\n    <button class=\"chip-btn\" data-case=\"budgetalert\">Budget Alert</button>\n    <button class=\"chip-btn\" data-case=\"quotaexceeded\">Quota Exceeded</button>\n  </div>\n  <div class=\"panel\" id=\"ts2-panel\"></div>\n</section>\n\n<!-- 28 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>Security</h4><ul style=\"margin-left:16px;\"><li>CIA = Confidentiality, Integrity, Availability</li><li>Defense in Depth = layered, independent controls</li><li>Zero Trust = never trust, always verify</li></ul></div>\n    <div class=\"card\"><h4>Cloud Guard</h4><ul style=\"margin-left:16px;\"><li>Detectors find problems, Responders act on them</li><li>Security Zones block; Cloud Guard detects+responds</li><li>Lifecycle: Resource \u2192 Detection \u2192 Problem \u2192 Investigation \u2192 Remediation \u2192 Closed</li></ul></div>\n    <div class=\"card\"><h4>Cost Management</h4><ul style=\"margin-left:16px;\"><li>Budgets alert at a % threshold, they don't hard-stop spend</li><li>BYOL saves money if you already hold active-support licenses</li></ul></div>\n    <div class=\"card\"><h4>Governance</h4><ul style=\"margin-left:16px;\"><li>Limits = provider ceiling (needs a support request to raise)</li><li>Quotas = self-imposed cap within a compartment</li><li>Organization Mgmt links tenancies for billing, not IAM</li></ul></div>\n  </div>\n  <table class=\"cmp mt-lg\"><tr><th>Important CLI Commands</th></tr>\n    <tr><td class=\"mono\">oci cloud-guard target list</td></tr>\n    <tr><td class=\"mono\">oci cloud-guard problem list</td></tr>\n    <tr><td class=\"mono\">oci budgets budget list</td></tr>\n    <tr><td class=\"mono\">oci limits resource-availability get</td></tr>\n    <tr><td class=\"mono\">oci limits value list</td></tr>\n    <tr><td class=\"mono\">oci organizations organization list</td></tr>\n    <tr><td class=\"mono\">oci cloud-advisor recommendation list</td></tr>\n  </table>\n</section>\n\n<!-- 29 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Flash Cards</h2>\n  <p class=\"dek\">Click a card to flip it.</p>\n  <div class=\"flash-wrap\" id=\"flash-wrap2\"></div>\n</section>\n\n<!-- 30 QUIZ -->\n<section class=\"chapter reveal\" id=\"sec-quiz2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Certification Readiness Quiz</h2>\n  <p class=\"dek\">20 scenario-style questions.</p>\n  <div id=\"quiz-wrap2\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score2\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 31 CERTIFICATE PREVIEW -->\n<section class=\"chapter reveal\" id=\"sec-cert2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">31</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div id=\"badge-wrap2\" class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle2\"><span id=\"badge-pct2\">0%</span></div>\n    <h3 id=\"badge-title2\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub2\">Complete every section and the quiz to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\" id=\"cert-name-display\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 2: Security, Cloud Guard &amp; Governance</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display\">0/20</span> \u00b7 Date: <span id=\"cert-date-display\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Security, Governance &amp; Cost Management \u2014 Day 2 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0 };\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initCIA(); initCastle(); initZeroTrust(); initSharedRespSecurity(); initCloudGuardToggle();\n  initDetectors(); initResponders(); initLifecycle(); initSecurityZones(); initSecurityAdvisor();\n  initCgDecisionTree(); initBillingDashboard(); initBudgetWizard(); initCostAnalysis(); initBYOL();\n  initMarketplace(); initRightSizing(); initGovPyramid(); initServiceLimits(); initQuotaDesigner();\n  initCloudAdvisor(); initComplianceMatrix(); initConsoleSim2(); initTerminal2(); initTroubleshootLab2();\n  initFlashcards2(); initQuiz2(); updateBadge2();\n});\n\nfunction initParticles(){\n  const c = document.getElementById('particles'); const ctx = c.getContext('2d');\n  let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N = Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){\n    ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar = document.getElementById('progress-bar'); const heroProgress = document.getElementById('hero-progress');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY; const docH = document.documentElement.scrollHeight - window.innerHeight;\n    const pct = docH>0 ? (scrollTop/docH)*100 : 0;\n    bar.style.width = pct+'%'; if(heroProgress) heroProgress.textContent = Math.round(pct)+'%';\n    window.__lastScrollPct2 = pct; updateBadge2(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections = document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect = sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=> a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title = sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML = matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- CIA triad ---------- */\nfunction initCIA(){\n  const nodes = document.querySelectorAll('.cia-node'); if(!nodes.length) return;\n  const detail = document.getElementById('cia-detail');\n  const info = {\n    confidentiality: 'Breach example: a hospital database is exposed, leaking patient records (healthcare). In banking, a leaked customer PII dump enables fraud. Impact: loss of trust, regulatory fines, identity theft.',\n    integrity: 'Attack example: a military targeting database is silently altered, or a bank ledger is tampered with mid-transaction. Impact: decisions or transactions based on corrupted data \u2014 sometimes worse than a total outage.',\n    availability: 'Outage example: a government benefits portal goes down during open enrollment, or a cloud provider region fails during peak trading hours. Impact: lost revenue, SLA penalties, public trust damage.'\n  };\n  nodes.forEach(n=>{\n    n.addEventListener('click', ()=>{\n      nodes.forEach(x=>x.classList.remove('active'));\n      n.classList.add('active');\n      detail.textContent = info[n.dataset.k];\n    });\n  });\n}\n\n/* ---------- defense in depth castle ---------- */\nfunction initCastle(){\n  const wrap = document.getElementById('castle-layers'); if(!wrap) return;\n  const layers = ['User Awareness','Identity & Access','Network Perimeter','Compute Hardening','Application Security','Database Controls','Monitoring & Logging','Encryption'];\n  wrap.innerHTML = layers.map((l,i)=>`<div class=\"castle-layer\" data-i=\"${i}\"><span class=\"cl-name\">${l}</span><button class=\"chip-btn\" data-remove=\"${i}\">Remove</button></div>`).join('');\n  const msg = document.getElementById('castle-msg');\n  let removed = new Set();\n  function render(){\n    wrap.querySelectorAll('.castle-layer').forEach((el,i)=> el.classList.toggle('removed', removed.has(i)));\n    if(removed.size===0) { msg.textContent='All 8 layers intact. An attacker is stopped immediately.'; msg.style.color='var(--text-3)'; }\n    else { msg.textContent = `${removed.size} layer(s) removed. Weakest remaining layer: \"${layers[Math.max(...removed)] || layers[0]}\" \u2014 attacker progress depends on which layers are gone.`; msg.style.color='var(--amber)'; }\n  }\n  wrap.addEventListener('click', e=>{\n    if(e.target.dataset.remove!==undefined && e.target.dataset.remove!==''){ removed.add(parseInt(e.target.dataset.remove)); render(); }\n  });\n  document.getElementById('castle-reset').addEventListener('click', ()=>{ removed.clear(); render(); });\n  document.getElementById('castle-attack').addEventListener('click', ()=>{\n    if(removed.size >= layers.length){ msg.textContent='\ud83d\udca5 Full breach \u2014 every layer was removed.'; msg.style.color='var(--red-bright)'; }\n    else if(removed.size === 0){ msg.textContent='\ud83d\udee1 Attack fully repelled \u2014 defense in depth held.'; msg.style.color='var(--green)'; }\n    else { msg.textContent = `\u26a0 Attacker penetrated ${removed.size} of ${layers.length} layers before being stopped.`; msg.style.color='var(--amber)'; }\n  });\n  render();\n}\n\n/* ---------- zero trust flow ---------- */\nfunction initZeroTrust(){\n  const flow = document.getElementById('zt-flow'); if(!flow) return;\n  const nodes = ['User','Identity Check','Device Posture','Policy Engine','MFA','Risk Score','Access Granted'];\n  flow.innerHTML = nodes.map((n,i)=> (i>0?'<span class=\"zt-arrow\">\u2192</span>':'') + `<div class=\"zt-node\" data-i=\"${i}\">${n}</div>`).join('');\n  const msg = document.getElementById('zt-msg');\n  document.getElementById('zt-play').addEventListener('click', ()=>{\n    const els = flow.querySelectorAll('.zt-node'); els.forEach(e=>e.classList.remove('active'));\n    nodes.forEach((n,i)=> setTimeout(()=>{ els[i].classList.add('active'); msg.textContent = `Evaluating: ${n}\u2026 nothing is trusted by default, even if this step passed before.`; if(i===nodes.length-1) msg.textContent='\u2713 Access granted \u2014 but only for this single request; the next request re-evaluates everything.'; }, i*450));\n  });\n}\n\n/* ---------- shared responsibility (security lens) ---------- */\nfunction initSharedRespSecurity(){\n  const wrap = document.getElementById('sr-security-layers'); if(!wrap) return;\n  const data = {\n    iaas: [['Data','you'],['Application','you'],['Identity & Access','shared'],['OS & Middleware','you'],['Virtualization','oracle'],['Physical Hardware','oracle'],['Network Backbone','oracle']],\n    paas: [['Data','you'],['Application','you'],['Identity & Access','shared'],['OS & Middleware','oracle'],['Virtualization','oracle'],['Physical Hardware','oracle'],['Network Backbone','oracle']],\n    saas: [['Data','shared'],['Application','oracle'],['Identity & Access','shared'],['OS & Middleware','oracle'],['Virtualization','oracle'],['Physical Hardware','oracle'],['Network Backbone','oracle']],\n  };\n  function render(model){\n    wrap.innerHTML = data[model].map(([name,who])=>`<div class=\"resp-layer-row\"><span class=\"name\">${name}</span><span class=\"who who-${who}\">${who==='you'?'Customer':who==='oracle'?'Oracle':'Shared'}</span></div>`).join('');\n  }\n  document.querySelectorAll('#sr-model-btns .chip-btn').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#sr-model-btns .chip-btn').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active'); render(btn.dataset.model);\n    });\n  });\n  render('iaas');\n}\n\n;\n\n/* ---------- cloud guard enable toggle ---------- */\nfunction initCloudGuardToggle(){\n  const t = document.getElementById('cg-enable-toggle'); if(!t) return;\n  const msg = document.getElementById('cg-enable-msg');\n  t.addEventListener('change', ()=>{\n    msg.innerHTML = t.checked ? 'Cloud Guard is currently <strong style=\"color:var(--green);\">enabled</strong> \u2014 default detector &amp; responder recipes are now attached to the root compartment.' : 'Cloud Guard is currently <strong>disabled</strong>.';\n  });\n}\n\n/* ---------- detectors ---------- */\nfunction initDetectors(){\n  const toggles = document.querySelectorAll('.det-toggle'); if(!toggles.length) return;\n  const msg = document.getElementById('detector-msg');\n  const findings = {\n    config: 'Example finding: \"Object Storage bucket bkt-invoices is publicly readable\" \u2014 a Configuration Detector finding.',\n    activity: 'Example finding: \"User j.doe called 40 IAM APIs in 2 minutes from a new location\" \u2014 an Activity Detector finding.',\n    threat: 'Example finding: \"Inbound traffic from a known malicious IP was blocked\" \u2014 a Threat Detector finding.'\n  };\n  let active = [];\n  toggles.forEach(t=>{\n    t.addEventListener('change', ()=>{\n      if(t.checked) active.push(findings[t.dataset.det]); else active = active.filter(f=>f!==findings[t.dataset.det]);\n      msg.innerHTML = active.length ? active.join('<br>') : 'Enable a detector to see an example finding.';\n    });\n  });\n}\n\n/* ---------- responders ---------- */\nfunction initResponders(){\n  const cards = document.querySelectorAll('.responder-card'); if(!cards.length) return;\n  const msg = document.getElementById('responder-msg');\n  const effect = {\n    notify: 'Notify: Cloud Guard sends an alert to the configured topic/email. The bucket remains public \u2014 human follow-up required.',\n    quarantine: 'Quarantine: the bucket is tagged and isolated from normal workflows pending review, without deleting data.',\n    removeip: 'Remove Public IP: not applicable to a bucket directly, but this responder strips public IPs from compute/LB resources automatically.',\n    disable: 'Disable User: the identity that made the bucket public is suspended, preventing further changes while it\\'s investigated.'\n  };\n  cards.forEach(c=>{\n    c.addEventListener('click', ()=>{\n      cards.forEach(x=>x.classList.remove('selected')); c.classList.add('selected');\n      msg.textContent = effect[c.dataset.r];\n    });\n  });\n}\n\n/* ---------- problem lifecycle ---------- */\nfunction initLifecycle(){\n  const wrap = document.getElementById('lifecycle-pipeline'); if(!wrap) return;\n  const steps = ['Resource','Misconfiguration','Detection','Problem Created','Investigation','Remediation','Resolution','Closed'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"pipe-arrow\">\u2192</span>':'')+`<div class=\"pipe-step\" data-i=\"${i}\">${s}</div>`).join('');\n  document.getElementById('lifecycle-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.pipe-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=> els[i].classList.add('lit'), i*350));\n  });\n}\n\n/* ---------- security zones ---------- */\nfunction initSecurityZones(){\n  const buttons = document.querySelectorAll('[data-sz]'); if(!buttons.length) return;\n  const enableToggle = document.getElementById('sz-enable');\n  const result = document.getElementById('sz-result');\n  const reasons = {\n    bucket: 'Public buckets are prohibited inside a Maximum Security Zone \u2014 data must never be internet-readable.',\n    igw: 'Internet Gateways are blocked \u2014 Security Zone compartments must remain isolated from direct internet ingress/egress.',\n    publicip: 'Public IPs on compute/LB resources are blocked to prevent direct internet exposure.',\n    weakenc: 'Weak or disabled encryption is blocked \u2014 all storage must use OCI-managed or customer-managed strong encryption.'\n  };\n  buttons.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      if(enableToggle.checked){\n        result.className='sz-result blocked';\n        result.textContent = `\ud83d\udeab Request blocked. ${reasons[btn.dataset.sz]}`;\n      } else {\n        result.className='sz-result allowed';\n        result.textContent = `\u26a0 Allowed \u2014 Security Zone is disabled, so this compartment now behaves like a normal one (not recommended for production).`;\n      }\n    });\n  });\n}\n\n/* ---------- security advisor ---------- */\nfunction initSecurityAdvisor(){\n  const rows = document.querySelectorAll('#sec-secadvisor .rec-row'); if(!rows.length) return;\n  const ring = document.getElementById('advisor-ring'); const valEl = document.getElementById('advisor-score-val');\n  let score = 55;\n  rows.forEach(row=>{\n    row.querySelector('.fix-btn').addEventListener('click', function(){\n      if(row.classList.contains('fixed')) return;\n      row.classList.add('fixed'); this.textContent='Fixed \u2713'; this.disabled = true;\n      score = Math.min(100, score + Math.floor(Math.random()*6)+8);\n      ring.style.setProperty('--score', score); valEl.textContent = score;\n    });\n  });\n}\n\n/* ---------- cloud guard deployment decision tree ---------- */\nfunction initCgDecisionTree(){\n  const yesBtn = document.querySelector('[data-dt=\"yes\"]'); if(!yesBtn) return;\n  const noBtn = document.querySelector('[data-dt=\"no\"]');\n  const ry = document.getElementById('dt-result-yes'); const rn = document.getElementById('dt-result-no');\n  yesBtn.addEventListener('click', ()=>{ ry.style.display='block'; rn.style.display='none'; });\n  noBtn.addEventListener('click', ()=>{ rn.style.display='block'; ry.style.display='none'; });\n}\n\n;\n\n/* ---------- billing dashboard charts ---------- */\nfunction initBillingDashboard(){\n  const trendCanvas = document.getElementById('costTrendChart'); if(!trendCanvas) return;\n  const tctx = trendCanvas.getContext('2d');\n  const days = Array.from({length:14}, (_,i)=> 150 + Math.round(Math.sin(i/2)*40) + Math.round(Math.random()*30) + i*6);\n  function drawTrend(){\n    const w = trendCanvas.width = trendCanvas.clientWidth || 400, h = trendCanvas.height = 200;\n    tctx.clearRect(0,0,w,h);\n    const max = Math.max(...days);\n    tctx.beginPath();\n    days.forEach((d,i)=>{\n      const x = (i/(days.length-1))*(w-20)+10;\n      const y = h-20-(d/max)*(h-40);\n      if(i===0) tctx.moveTo(x,y); else tctx.lineTo(x,y);\n    });\n    tctx.strokeStyle = '#ff5a3c'; tctx.lineWidth = 2; tctx.stroke();\n    const grad = tctx.createLinearGradient(0,0,0,h);\n    grad.addColorStop(0,'rgba(199,70,52,0.3)'); grad.addColorStop(1,'rgba(199,70,52,0)');\n    tctx.lineTo(w-10,h-20); tctx.lineTo(10,h-20); tctx.closePath(); tctx.fillStyle = grad; tctx.fill();\n  }\n  drawTrend(); window.addEventListener('resize', drawTrend);\n\n  const pieCanvas = document.getElementById('costPieChart'); const pctx = pieCanvas.getContext('2d');\n  const services = [['Compute',1850,'#ff5a3c'],['Database',1230,'#4f8cff'],['Storage',680,'#e8a33d'],['Networking',540,'#3ec28f'],['Other',520,'#9096a2']];\n  function drawPie(){\n    const w = pieCanvas.width = 200, h = pieCanvas.height = 200;\n    pctx.clearRect(0,0,w,h);\n    const total = services.reduce((a,s)=>a+s[1],0);\n    let start = -Math.PI/2;\n    services.forEach(([name,val,color])=>{\n      const angle = (val/total)*Math.PI*2;\n      pctx.beginPath(); pctx.moveTo(w/2,h/2); pctx.arc(w/2,h/2,90,start,start+angle); pctx.closePath();\n      pctx.fillStyle = color; pctx.fill();\n      start += angle;\n    });\n    document.getElementById('pie-legend').innerHTML = services.map(([name,val,color])=>`<div><span class=\"sw\" style=\"background:${color}\"></span>${name} \u2014 $${val}</div>`).join('');\n  }\n  drawPie();\n}\n\n/* ---------- budget wizard ---------- */\nfunction initBudgetWizard(){\n  const amount = document.getElementById('wz-amount'); if(!amount) return;\n  const threshold = document.getElementById('wz-threshold');\n  amount.addEventListener('input', ()=> document.getElementById('wz-amount-val').textContent = '$'+parseInt(amount.value).toLocaleString());\n  threshold.addEventListener('input', ()=> document.getElementById('wz-threshold-val').textContent = threshold.value+'%');\n  function goto(n){\n    document.querySelectorAll('.wizard-panel').forEach(p=>p.classList.remove('active'));\n    document.getElementById('wz-'+n).classList.add('active');\n    for(let i=1;i<=3;i++) document.getElementById('wz-bar-'+i).classList.toggle('done', i<=n);\n    if(n===3){\n      const scope = document.getElementById('wz-scope').value;\n      const recipients = document.getElementById('wz-recipients').value || 'no recipients set';\n      document.getElementById('wz-summary').innerHTML = `Budget: <strong>$${parseInt(amount.value).toLocaleString()}/mo</strong> on <strong>${scope}</strong>, alerting at <strong>${threshold.value}%</strong> to <strong>${recipients}</strong>.`;\n      document.getElementById('wz-gauge').style.width = '0%';\n      document.getElementById('wz-status').textContent = 'Spend: $0 (0% of budget)';\n    }\n  }\n  document.getElementById('wz-next-1').addEventListener('click', ()=>goto(2));\n  document.getElementById('wz-back-2').addEventListener('click', ()=>goto(1));\n  document.getElementById('wz-next-2').addEventListener('click', ()=>goto(3));\n  document.getElementById('wz-back-3').addEventListener('click', ()=>goto(2));\n  document.getElementById('wz-create').addEventListener('click', function(){\n    this.textContent = '\u2713 Budget Created'; this.disabled = true;\n    document.getElementById('wz-simulate-spend').style.display = 'inline-flex';\n  });\n  document.getElementById('wz-simulate-spend').addEventListener('click', ()=>{\n    const thr = parseInt(threshold.value);\n    const pct = thr + 15;\n    document.getElementById('wz-gauge').style.width = Math.min(100,pct)+'%';\n    document.getElementById('wz-status').innerHTML = `<strong style=\"color:var(--red-bright);\">\u26a0 Spend crossed ${thr}% threshold</strong> \u2014 alert sent to configured recipients.`;\n  });\n}\n\n/* ---------- cost analysis ---------- */\nfunction initCostAnalysis(){\n  const canvas = document.getElementById('analysisChart'); if(!canvas) return;\n  const ctx = canvas.getContext('2d');\n  const data = {\n    all: {Compute:1850, Database:1230, Storage:680, Networking:540, Other:520},\n    compute: {'VM.Standard.E4':1200,'VM.Standard.E5':450,'Bare Metal':200},\n    storage: {'Block Volume':400,'Object Storage':220,'File Storage':60},\n    database: {'Autonomous DB':900,'Exadata':330},\n    network: {'Load Balancer':180,'FastConnect':280,'Data Transfer':80},\n  };\n  function draw(key){\n    const set = data[key]; const entries = Object.entries(set);\n    const total = entries.reduce((a,[,v])=>a+v,0);\n    const w = canvas.width = canvas.clientWidth || 600, h = canvas.height = 220;\n    ctx.clearRect(0,0,w,h);\n    const max = Math.max(...entries.map(e=>e[1]));\n    const barW = (w-40)/entries.length - 16;\n    entries.forEach(([name,val],i)=>{\n      const x = 20 + i*((w-40)/entries.length);\n      const bh = (val/max)*(h-60);\n      const grad = ctx.createLinearGradient(0,h-30-bh,0,h-30);\n      grad.addColorStop(0,'#ff5a3c'); grad.addColorStop(1,'#c74634');\n      ctx.fillStyle = grad; ctx.fillRect(x, h-30-bh, barW, bh);\n      ctx.fillStyle = '#a7acb8'; ctx.font='10px monospace'; ctx.textAlign='center';\n      ctx.fillText(name, x+barW/2, h-14);\n      ctx.fillStyle='#eef0f3'; ctx.font='bold 11px monospace';\n      ctx.fillText('$'+val, x+barW/2, h-36-bh);\n    });\n    document.getElementById('analysis-total').textContent = `Total: $${total.toLocaleString()} for the selected filter this month.`;\n  }\n  document.querySelectorAll('[data-cf]').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('[data-cf]').forEach(b=>b.classList.remove('active')); btn.classList.add('active');\n      draw(btn.dataset.cf);\n    });\n  });\n  draw('all');\n}\n\n/* ---------- BYOL calculator ---------- */\nfunction initBYOL(){\n  const btns = document.querySelectorAll('#byol-workload-btns .chip-btn'); if(!btns.length) return;\n  const costs = { small:{li:1400, byol:600}, medium:{li:5200, byol:2100}, large:{li:19800, byol:7600} };\n  function render(w){\n    const c = costs[w];\n    document.getElementById('byol-li-cost').textContent = '$'+c.li.toLocaleString()+'/mo';\n    document.getElementById('byol-byol-cost').textContent = '$'+c.byol.toLocaleString()+'/mo';\n    const savings = Math.round((1-c.byol/c.li)*100);\n    document.getElementById('byol-reco').innerHTML = `If you already hold active-support Oracle licenses, BYOL saves ~<strong style=\"color:var(--green);\">${savings}%</strong> here. If not, License Included avoids any licensing compliance overhead.`;\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.w); }));\n  render('small');\n}\n\n/* ---------- marketplace ---------- */\nfunction initMarketplace(){\n  const grid = document.getElementById('mp-grid'); if(!grid) return;\n  const listings = [\n    {name:'MySQL HeatWave', cat:'db', ic:'\ud83d\uddc4'}, {name:'PostgreSQL', cat:'db', ic:'\ud83d\udc18'},\n    {name:'Fortinet FortiGate', cat:'sec', ic:'\ud83d\udee1'}, {name:'Palo Alto VM-Series', cat:'sec', ic:'\ud83e\uddf1'},\n    {name:'Splunk Enterprise', cat:'mon', ic:'\ud83d\udcc8'}, {name:'Datadog Agent', cat:'mon', ic:'\ud83d\udc36'},\n    {name:'Hugging Face Hub', cat:'ai', ic:'\ud83e\udd17'}, {name:'AI Vision Toolkit', cat:'ai', ic:'\ud83d\udc41'},\n    {name:'F5 BIG-IP', cat:'net', ic:'\ud83c\udf10'}, {name:'Cisco CSR 1000v', cat:'net', ic:'\ud83d\udce1'},\n  ];\n  function render(filter){\n    grid.innerHTML = listings.filter(l=> filter==='all' || l.cat===filter).map(l=>`<div class=\"mp-card\" data-name=\"${l.name}\"><div class=\"mp-ic\">${l.ic}</div><div>${l.name}</div></div>`).join('');\n  }\n  document.querySelectorAll('#mp-cat-btns .chip-btn').forEach(btn=>{\n    btn.addEventListener('click', ()=>{ document.querySelectorAll('#mp-cat-btns .chip-btn').forEach(b=>b.classList.remove('active')); btn.classList.add('active'); render(btn.dataset.cat); });\n  });\n  grid.addEventListener('click', e=>{\n    const card = e.target.closest('.mp-card'); if(!card) return;\n    const status = document.getElementById('mp-deploy-status');\n    status.style.display='block'; status.textContent = `\u23f3 Deploying \"${card.dataset.name}\"\u2026`;\n    setTimeout(()=>{ status.textContent = `\u2713 \"${card.dataset.name}\" deployed successfully to compartment Sandbox.`; }, 900);\n  });\n  render('all');\n}\n\n/* ---------- right sizing ---------- */\nfunction initRightSizing(){\n  const shapes = document.querySelectorAll('.rs-shape'); if(!shapes.length) return;\n  const savings = document.getElementById('rs-savings');\n  const info = {\n    over: '\ud83d\udcc9 Advisor recommendation: <strong>downsize</strong> from VM.Standard.E4.Flex (8 OCPU) to 2 OCPU \u2014 average CPU utilization is only 9%. Estimated savings: <strong style=\"color:var(--green);\">~$210/month</strong>.',\n    under: '\ud83d\udcc8 Advisor recommendation: <strong>upsize</strong> from 2 OCPU to 4 OCPU \u2014 average CPU utilization is 96%, this workload is CPU-constrained and at risk of throttling.'\n  };\n  shapes.forEach(s=>{\n    s.addEventListener('click', ()=>{\n      shapes.forEach(x=>x.classList.remove('selected')); s.classList.add('selected');\n      savings.style.display='block'; savings.innerHTML = info[s.dataset.rs];\n    });\n  });\n}\n\n;\n\n/* ---------- governance pyramid ---------- */\nfunction initGovPyramid(){\n  const tiers = document.querySelectorAll('#gov-pyramid .pyr-tier'); if(!tiers.length) return;\n  const detail = document.getElementById('gov-detail');\n  const info = {\n    enterprise: 'Enterprise Architecture: the top-level blueprint aligning IT strategy with business goals \u2014 sets direction for everything below.',\n    landing: 'Landing Zone: a pre-built, secure, compliant baseline environment (network, IAM, logging) new workloads are deployed into.',\n    policies: 'Policies & Standards: the concrete rules (naming, tagging, IAM policies, security baselines) that enforce the architecture.',\n    processes: 'Operational Processes: the day-to-day procedures \u2014 change management, incident response, cost reviews \u2014 that keep governance running.'\n  };\n  tiers.forEach(t=> t.addEventListener('click', ()=>{ detail.textContent = info[t.dataset.g]; }));\n}\n\n/* ---------- service limits ---------- */\nfunction initServiceLimits(){\n  const btn = document.getElementById('limit-request'); if(!btn) return;\n  const wrap = document.getElementById('limit-pipeline'); const msg = document.getElementById('limit-msg');\n  const steps = ['Request Submitted','Support Ticket Created','Oracle Review','Approved','Limit Increased'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"pipe-arrow\">\u2192</span>':'')+`<div class=\"pipe-step\" data-i=\"${i}\">${s}</div>`).join('');\n  btn.addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.pipe-step'); els.forEach(e=>e.classList.remove('lit'));\n    msg.textContent = 'Submitting request\u2026';\n    steps.forEach((s,i)=> setTimeout(()=>{ els[i].classList.add('lit'); msg.textContent = `Status: ${s}`; if(i===steps.length-1) msg.textContent='\u2713 Limit increased to 150 compute cores.'; }, i*500));\n  });\n}\n\n/* ---------- quota designer validator ---------- */\nfunction initQuotaDesigner(){\n  const btn = document.getElementById('quota-validate'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const val = document.getElementById('quota-input').value.trim();\n    const verdict = document.getElementById('quota-verdict');\n    const pattern = /^(set|zero)\\s+[\\w-]+\\s+quotas\\s+[\\w-]+\\s+to\\s+\\d+\\s+in\\s+(compartment|tenancy)(\\s+[\\w-]+)?$/i;\n    if(pattern.test(val)){ verdict.className='policy-verdict ok'; verdict.textContent='\u2713 Valid quota statement.'; }\n    else { verdict.className='policy-verdict bad'; verdict.textContent='\u2717 Expected form: set <service> quotas <resource> to <number> in compartment <Name>'; }\n  });\n}\n\n/* ---------- cloud advisor ---------- */\nfunction initCloudAdvisor(){\n  const rows = document.querySelectorAll('#sec-cladvisor .rec-row'); if(!rows.length) return;\n  const ring = document.getElementById('cladvisor-ring'); const valEl = document.getElementById('cladvisor-score-val');\n  let score = 62;\n  rows.forEach(row=>{\n    row.querySelector('.ca-fix-btn').addEventListener('click', function(){\n      if(row.classList.contains('fixed')) return;\n      row.classList.add('fixed'); this.textContent='Fixed \u2713'; this.disabled=true;\n      score = Math.min(100, score + Math.floor(Math.random()*5)+7);\n      ring.style.setProperty('--score', score); valEl.textContent = score;\n    });\n  });\n}\n\n/* ---------- compliance matrix ---------- */\nfunction initComplianceMatrix(){\n  const cards = document.querySelectorAll('#compliance-grid .compliance-card'); if(!cards.length) return;\n  const detail = document.getElementById('compliance-detail');\n  const info = {\n    iso: 'ISO 27001: an international standard for information security management systems (ISMS) \u2014 process-focused, broadly applicable.',\n    soc: 'SOC 1/2: audit reports on controls relevant to financial reporting (SOC 1) or security/availability/confidentiality (SOC 2) \u2014 common in vendor due diligence.',\n    pci: 'PCI DSS: required for any organization storing, processing, or transmitting cardholder data.',\n    hipaa: 'HIPAA: US healthcare regulation protecting patient health information (PHI) \u2014 relevant to any healthcare workload.',\n    gdpr: 'GDPR: EU regulation governing personal data of EU residents \u2014 affects data residency, consent, and breach notification.',\n    residency: 'Data Residency: legal/contractual requirements that data physically remain within a specific country or region \u2014 satisfied by choosing the right OCI region.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=>{ detail.textContent = info[c.dataset.c]; }));\n}\n\n;\n\n/* ---------- console simulator 2 ---------- */\nfunction initConsoleSim2(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel2]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel2').forEach(p=>p.style.display='none');\n      document.getElementById('panel2-'+item.dataset.panel2).style.display='';\n    });\n  });\n}\n\n/* ---------- CLI terminal 2 ---------- */\nfunction initTerminal2(){\n  const out = document.getElementById('term-out2'); const input = document.getElementById('term-input2'); if(!input) return;\n  const responses = {\n    'help': `Available commands:\n  oci cloud-guard target list\n  oci cloud-guard problem list\n  oci budgets budget list\n  oci limits resource-availability get\n  oci limits value list\n  oci organizations organization list\n  oci cloud-advisor recommendation list\n  clear`,\n    'oci cloud-guard target list': `{\n  \"data\": [{\"display-name\": \"root-compartment-target\", \"target-resource-type\": \"COMPARTMENT\", \"status\": \"ENABLED\"}]\n}`,\n    'oci cloud-guard problem list': `{\n  \"data\": [\n    {\"description\": \"Public bucket detected\", \"risk-level\": \"HIGH\", \"lifecycle-detail\": \"OPEN\"},\n    {\"description\": \"Root API key in use\", \"risk-level\": \"MEDIUM\", \"lifecycle-detail\": \"OPEN\"}\n  ]\n}`,\n    'oci budgets budget list': `{\n  \"data\": [{\"display-name\": \"Production Monthly\", \"amount\": 5000, \"actual-spend\": 4820}]\n}`,\n    'oci limits resource-availability get': `{\n  \"data\": {\"available\": 8, \"used\": 92, \"fractional-usage\": 0.92}\n}`,\n    'oci limits value list': `{\n  \"data\": [{\"name\": \"compute-core-count\", \"value\": 100}, {\"name\": \"vcn-count\", \"value\": 5}]\n}`,\n    'oci organizations organization list': `{\n  \"data\": [{\"display-name\": \"Parent Organization\", \"lifecycle-state\": \"ACTIVE\", \"linked-tenancies\": 3}]\n}`,\n    'oci cloud-advisor recommendation list': `{\n  \"data\": [\n    {\"name\": \"Terminate idle instances\", \"category\": \"COST\"},\n    {\"name\": \"Enable MFA for admin group\", \"category\": \"SECURITY\"}\n  ]\n}`\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  function print(cmd, text, isErr){\n    const line = document.createElement('div');\n    line.innerHTML = `<div class=\"cmdline\">${esc(cmd)}</div><div style=\"color:${isErr?'#ff8a7a':'#c9f7d8'}; margin:4px 0 12px; white-space:pre-wrap;\">${esc(text)}</div>`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  }\n  print('help','Welcome to the OCI CLI simulator. Type \"help\" for available commands.');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value='';\n    if(!cmd) return;\n    if(cmd==='clear'){ out.innerHTML=''; return; }\n    if(responses[cmd]){ print(cmd, responses[cmd]); return; }\n    print(cmd, 'Command not recognized in this simulator. Type \"help\" for the supported list.', true);\n  });\n}\n\n/* ---------- troubleshooting lab 2 ---------- */\nfunction initTroubleshootLab2(){\n  const btns = document.querySelectorAll('#ts2-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('ts2-panel');\n  const cases = {\n    cgproblem: {err:'Cloud Guard problem: \"Instance principal has manage permission on all-resources in tenancy.\"', hint:'Think about least privilege \u2014 does this identity really need tenancy-wide manage rights?', fix:'Fix: scope the dynamic group\\'s policy down to only the specific compartment and resource types it actually needs.'},\n    szerror: {err:'Error: \"Action blocked by Security Zone policy: cannot attach Internet Gateway in zone prod-zone.\"', hint:'Security Zones hard-block certain network configurations by design.', fix:'Fix: either use a private endpoint/service gateway instead of an Internet Gateway, or move the workload outside the Security Zone if internet access is truly required.'},\n    budgetalert: {err:'Alert: \"Production Monthly budget has exceeded 96% of $5,000.\"', hint:'Budgets alert, they don\\'t automatically stop spend.', fix:'Fix: investigate the Cost Analysis breakdown for the spike, then either increase the budget or terminate/rightsize the offending resources.'},\n    quotaexceeded: {err:'Error: \"QuotaExceeded: compute quota instance-count (20) reached in compartment Production.\"', hint:'Quotas are a self-imposed governance cap, separate from account-wide service Limits.', fix:'Fix: either request a quota increase via the quota statement, or terminate unused instances to free capacity within the existing quota.'}\n  };\n  function render(key){\n    const c = cases[key];\n    panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p>\n      <button class=\"chip-btn active mt-lg\" id=\"ts2-hint-btn\">\ud83d\udca1 Show hint</button>\n      <p class=\"small mt-lg\" id=\"ts2-hint\" style=\"display:none;\">${c.hint}</p>\n      <button class=\"chip-btn mt-lg\" id=\"ts2-fix-btn\" style=\"display:none;\">\u2713 Reveal fix</button>\n      <p class=\"small mt-lg\" id=\"ts2-fix\" style=\"display:none; color:var(--green);\">${c.fix}</p>`;\n    document.getElementById('ts2-hint-btn').addEventListener('click', function(){ document.getElementById('ts2-hint').style.display='block'; document.getElementById('ts2-fix-btn').style.display='inline-flex'; this.disabled=true; });\n    document.getElementById('ts2-fix-btn').addEventListener('click', function(){ document.getElementById('ts2-fix').style.display='block'; this.disabled=true; });\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.case); }));\n  render('cgproblem');\n}\n\n;\n\n/* ---------- flashcards 2 ---------- */\nfunction initFlashcards2(){\n  const wrap = document.getElementById('flash-wrap2'); if(!wrap) return;\n  const cards = [\n    ['CIA Triad', 'Confidentiality, Integrity, Availability'],\n    ['Defense in Depth', 'Multiple independent layered security controls'],\n    ['Zero Trust', 'Never trust, always verify \u2014 no implicit trust by network location'],\n    ['Detector Recipe', 'Rules Cloud Guard uses to flag misconfigurations/threats'],\n    ['Responder Recipe', 'Automated or manual actions taken on a detected problem'],\n    ['Security Zone', 'Hard-blocks non-compliant actions at request time'],\n    ['Security Advisor', 'A running score based on unresolved recommendations'],\n    ['Budget', 'Alerts at a spend threshold \u2014 does not hard-stop spend'],\n    ['BYOL', 'Bring Your Own License \u2014 cheaper if you already hold active support'],\n    ['Service Limit', 'A provider-side ceiling, raised via a support request'],\n    ['Quota', 'A self-imposed cap within a compartment, set by admins'],\n    ['Organization Management', 'Links multiple tenancies for centralized billing, not IAM'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- certification quiz 2 ---------- */\nfunction initQuiz2(){\n  const wrap = document.getElementById('quiz-wrap2'); if(!wrap) return;\n  const Q = [\n    {q:'A hospital patient database is leaked to the public. Which part of the CIA triad was primarily violated?', o:['Availability','Confidentiality','Integrity','None of the above'], c:1, e:'Unauthorized disclosure of data is a confidentiality violation.'},\n    {q:'A bank\\'s transaction ledger is silently altered mid-transaction. This is primarily a violation of:', o:['Confidentiality','Availability','Integrity','Accounting'], c:2, e:'Unauthorized alteration of data is an integrity violation, even if no one reads it.'},\n    {q:'Defense in Depth is best described as:', o:['One very strong firewall','Multiple independent layered controls','Encrypting all data twice','Buying more security tools than competitors'], c:1, e:'Defense in Depth relies on multiple independent layers so a single failure isn\\'t catastrophic.'},\n    {q:'Under Zero Trust, a user who authenticated 5 minutes ago from the corporate VPN:', o:['Is automatically trusted for all further requests','Must still be re-evaluated for each new access request','Bypasses MFA for the rest of the day','Is exempt from conditional access'], c:1, e:'Zero Trust re-verifies continuously \u2014 no standing trust based on network location or prior success.'},\n    {q:'On a SaaS workload, who is primarily responsible for application-layer security patches?', o:['The customer','Oracle','Neither \u2014 SaaS has no patching','The end user'], c:1, e:'In SaaS, Oracle manages the application layer, including patching.'},\n    {q:'Which OCI service continuously monitors for misconfigurations and can automatically respond?', o:['Security Zones','Cloud Guard','Cloud Advisor','Vault'], c:1, e:'Cloud Guard combines detection (detectors) and automated/manual response (responders).'},\n    {q:'Which detector type would flag \"50 failed login attempts in 60 seconds from an unfamiliar IP\"?', o:['Configuration Detector','Activity Detector','Threat Detector','Managed List'], c:2, e:'Threat Detectors focus on known malicious patterns/signatures, including brute-force style activity from flagged sources; in Cloud Guard, this pattern is typically caught by threat-intel-driven detectors.'},\n    {q:'Which responder action would you choose to immediately stop further changes by a compromised identity?', o:['Notify','Quarantine','Disable User','Remove Public IP'], c:2, e:'Disable User suspends the identity outright, stopping any further malicious changes.'},\n    {q:'In the Cloud Guard problem lifecycle, what comes immediately after \"Detection\"?', o:['Remediation','Problem Created','Closed','Resource'], c:1, e:'The pipeline is: Resource \u2192 Misconfiguration \u2192 Detection \u2192 Problem Created \u2192 Investigation \u2192 Remediation \u2192 Resolution \u2192 Closed.'},\n    {q:'A Security Zone compartment rejects a request to attach an Internet Gateway. This demonstrates that Security Zones:', o:['Only detect issues, like Cloud Guard','Hard-block non-compliant actions at request time','Are identical to IAM policies','Only apply to storage buckets'], c:1, e:'Unlike Cloud Guard (detect + respond after the fact), Security Zones prevent the action outright.'},\n    {q:'The Security Advisor score is best described as:', o:['A fixed compliance certificate','A running score reflecting unresolved recommendations','A billing metric','A network latency measurement'], c:1, e:'It rises as recommendations are fixed and falls as new issues are found \u2014 a live, not static, score.'},\n    {q:'Should Cloud Guard be enabled at the tenancy root or at individual compartments if you want consistent, low-maintenance, tenancy-wide coverage?', o:['Individual compartments only','Tenancy root','Neither \u2014 it must be per-user','It cannot be scoped'], c:1, e:'Root-level enablement gives consistent, tenancy-wide visibility with a single recipe set to maintain.'},\n    {q:'A Budget alert firing at 80% threshold means:', o:['Spend is automatically capped at 80%','A notification is sent; spend continues unless someone acts','All resources are suspended','The tenancy is locked'], c:1, e:'Budgets are alerting mechanisms, not hard spending caps \u2014 action still requires a human (or automation you build separately).'},\n    {q:'BYOL licensing is the better cost choice when:', o:['You have no existing Oracle licenses','You already hold Oracle licenses with active support','You want Oracle to handle all compliance','You are using SaaS only'], c:1, e:'BYOL only saves money if you already own the license and are paying for active support \u2014 otherwise License Included is simpler.'},\n    {q:'A Compute Optimizer recommendation to downsize a VM from 8 OCPU to 2 OCPU is based primarily on:', o:['The VM\\'s uptime','Average observed CPU utilization','The compartment name','The user who created it'], c:1, e:'Right-sizing recommendations come from actual utilization metrics \u2014 low average CPU usage signals an oversized shape.'},\n    {q:'Which of these is a self-imposed governance cap (not a provider ceiling requiring a support ticket)?', o:['Service Limit','Quota','Availability Domain count','Realm boundary'], c:1, e:'Quotas are set by tenancy admins within existing Service Limits; Limits themselves are raised via Oracle support requests.'},\n    {q:'Organization Management primarily enables which capability across linked/child tenancies?', o:['Shared IAM users across all tenancies','Centralized billing while keeping IAM isolated','Merging all resources into one tenancy','Bypassing compartment quotas'], c:1, e:'Organization Management consolidates billing/discounts while keeping each tenancy\\'s IAM fully separate.'},\n    {q:'Which compliance framework is most directly relevant to an e-commerce company storing credit card numbers?', o:['HIPAA','PCI DSS','GDPR only','ISO 9001'], c:1, e:'PCI DSS specifically governs storage, processing, and transmission of cardholder data.'},\n    {q:'A quota statement fails validation: \"compute quotas instance-count to 20 in compartment Production\" (missing the leading verb). What\\'s the fix?', o:['Add \"Allow\" at the start','Add \"set\" or \"zero\" at the start','Remove \"in compartment\"','Replace \"quotas\" with \"policy\"'], c:1, e:'Quota statements start with \"set\" (or \"zero\" to remove a quota), not \"Allow\" like IAM policies.'},\n    {q:'Which is a better description of the relationship between Cloud Guard and Security Zones?', o:['They are the same feature with different names','Cloud Guard detects & responds after the fact; Security Zones block at request time','Security Zones replace the need for Cloud Guard entirely','Cloud Guard only works inside Security Zones'], c:1, e:'They are complementary: Security Zones are preventive guardrails, Cloud Guard is detective and responsive.'},\n  ];\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz2-${qi}\">\n      <div class=\"qtext\">${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q2-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{\n        if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect');\n      });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score2').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge2();\n    });\n  });\n}\n\n/* ---------- badge / certificate ---------- */\nfunction updateBadge2(){\n  const scrollPct = window.__lastScrollPct2 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle2'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct2').textContent = combined+'%';\n  const title = document.getElementById('badge-title2'); const sub = document.getElementById('badge-sub2');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Day 2 Complete'; sub.textContent='Certificate preview unlocked below.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the quiz.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the quiz to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
